CREATE TABLE public.review_seed AS
SELECT n,uuidv7() AS workspace_id,uuidv7() AS fleet_id,uuidv7() AS revision_id
FROM generate_series(1,1000) n;
CREATE TABLE public.review_tenant AS SELECT uuidv7() AS id;
INSERT INTO identity.tenants(id,name,created_at,updated_at)
SELECT id,'SQL plan review',now(),now() FROM public.review_tenant;
INSERT INTO identity.workspaces(id,tenant_id,name,created_at)
SELECT s.workspace_id,t.id,'Review workspace '||s.n,now() FROM public.review_seed s CROSS JOIN public.review_tenant t;
INSERT INTO fleet.fleets(id,workspace_id,tenant_id,name,status,required_tags,memory_reads_workspace,memory_publishes_workspace,resource_version,created_at,updated_at)
SELECT s.fleet_id,s.workspace_id,t.id,'Code review','active','{}'::text[],false,false,1,now(),now()
FROM public.review_seed s CROSS JOIN public.review_tenant t;
INSERT INTO fleet.revisions(id,fleet_id,revision,definition,canonical_digest,policy_semantics,created_at)
SELECT revision_id,fleet_id,1,'{}'::jsonb,repeat('0',64),'fixture',now() FROM public.review_seed;
UPDATE fleet.fleets f SET head_revision_id=s.revision_id FROM public.review_seed s WHERE f.id=s.fleet_id;
INSERT INTO vault.secrets(id,workspace_id,key_name,kek_version,dek_ciphertext,dek_nonce,dek_tag,secret_nonce,secret_ciphertext,secret_tag,meta_kind,meta_provider,meta_base_url,meta_has_key,created_at,updated_at)
SELECT uuidv7(),s.workspace_id,'provider-key-'||lpad(k::text,3,'0'),1,
sha256(convert_to(s.n::text||'/'||k,'UTF8')),decode(repeat('00',12),'hex'),decode(repeat('00',16),'hex'),
decode(repeat('00',12),'hex'),sha256(convert_to('synthetic/'||s.n||'/'||k,'UTF8'))||sha256(convert_to('plan/'||s.n||'/'||k,'UTF8')),
decode(repeat('00',16),'hex'),'provider','openai-compatible','https://provider.example/v1',true,now(),now()
FROM public.review_seed s CROSS JOIN generate_series(1,100) k;
INSERT INTO fleet.admissions(id,fleet_id,workspace_id,producer,producer_key,payload_digest,actor,event_type,request_json,event_created_at,created_at,updated_at)
SELECT uuidv7(),s.fleet_id,s.workspace_id,'steer',s.n||'/'||k,'fixture','fixture:operator','chat','{"message":"Review the source."}',now(),now(),now()
FROM public.review_seed s CROSS JOIN generate_series(1,100) k;
INSERT INTO fleet.obligations(id,fleet_id,workspace_id,provider,destination,event_id,answer,receipt,claim_expires_at,attempt_count,created_at,updated_at)
SELECT uuidv7(),s.fleet_id,s.workspace_id,'fixture','review',uuidv7(),'Synthetic review answer.',uuidv7(),clock_timestamp()+interval '1 hour',0,now(),now()
FROM public.review_seed s CROSS JOIN generate_series(1,100) k;
ANALYZE identity.workspaces;
ANALYZE fleet.fleets;
ANALYZE fleet.revisions;
ANALYZE vault.secrets;
ANALYZE fleet.admissions;
ANALYZE fleet.obligations;
SELECT json_build_object('workspaces',(SELECT count(*) FROM identity.workspaces),'fleets',(SELECT count(*) FROM fleet.fleets),'secrets',(SELECT count(*) FROM vault.secrets),'admissions',(SELECT count(*) FROM fleet.admissions),'obligations',(SELECT count(*) FROM fleet.obligations));
